<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sell Point</title><style>body{font-family:Arial;margin:0;background:#f4f6f8}.wrap{max-width:1000px;margin:auto;padding:25px}.card{background:#fff;border-radius:14px;padding:20px;margin-bottom:15px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.btn{border:0;border-radius:10px;padding:9px 14px;background:#1154b4;color:#fff;cursor:pointer}.danger{background:#dc3545}.input{padding:10px;width:100%;box-sizing:border-box;border:1px solid #ddd;border-radius:9px}@media(max-width:600px){.grid{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="card"><h2>Buy Seller Point ID List</h2>@if(!$status)<p>Pending Withdrawal Point: <b>{{ $pending }}</b></p>@endif<p>Balance Point: <b>{{ $balance }}</b></p><p>1 Point = <b>{{ $conv }} Rs</b></p></div><div class="card"><h3>Available Seller IDs</h3>@foreach($users as $u)<div style="display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid #eee"><span>{{ $u->username }} — {{ $u->firstname }} {{ $u->lastname }}</span><button class="btn" onclick="sell({{ $u->user_id }})">Send</button></div>@endforeach</div></div><script>function sell(id){let p=prompt('Enter point');if(!p)return;fetch('{{ route('student.sellpoint.add') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}'},body:JSON.stringify({user_id:id,point:p})}).then(r=>r.json()).then(x=>{alert(x.success||x.error);if(x.success)location.reload()})}</script></body></html>